#include <cstdio>
using namespace std;

int main() {
    int a, b;
    scanf("%d-%d", &a, &b); // 標準入力から形式を指定して整数を 2 つ読み込む
    ++b; // ステージを進めてみて
    if (b > 8) { // ステージ 8 を越えていたら
        ++a; // ワールドを進めて
        b = 1; // ステージを戻す
    }
    printf("%d-%d\n", a, b); // 形式を指定して出力する
    return 0;
}
